lemmas.interchange:
{A A' A'' B B' B'' : Obj} {a : A ⇒ A'} {b : B ⇒ B'} {c : A' ⇒ A''}
{d : B' ⇒ B''} →
c ⊗₁ d ∘ a ⊗₁ b ≈ (c ∘ a) ⊗₁ (d ∘ b)

lemmas.swapMiddle:
{A = X : Obj} {A' = X' : Obj} {B' = Y : Obj} {B'' = Y' : Obj}
(f : X ⇒ X') (g : Y ⇒ Y') →
id ⊗₁ g ∘ f ⊗₁ id ≈ f ⊗₁ id ∘ id ⊗₁ g

lemma_normal.swapMiddle:
{A = X : Obj} {A' = X' : Obj} {B' = Y : Obj} {B'' = Y' : Obj}
(f : X ⇒ X') (g : Y ⇒ Y') →
⊗.F₁ (id , g) ∘ ⊗.F₁ (f , id) ≈ ⊗.F₁ (f , id) ∘ ⊗.F₁ (id , g)

lemma_normal.homomorphism:
{X = B₁ : Data.Product.Σ Obj (λ A₁ → Obj)}
{Y = y : Data.Product.Σ Obj (λ x → Obj)}
{Z : Data.Product.Σ Obj (λ g → Obj)}
{f
 : Data.Product.Σ (B₁ .Data.Product.proj₁ ⇒ y .Data.Product.proj₁)
   (λ x → B₁ .Data.Product.proj₂ ⇒ y .Data.Product.proj₂)}
{g
 : Data.Product.Σ (y .Data.Product.proj₁ ⇒ Z .Data.Product.proj₁)
   (λ x → y .Data.Product.proj₂ ⇒ Z .Data.Product.proj₂)} →
⊗.F₁
(g .Data.Product.proj₁ ∘ f .Data.Product.proj₁ ,
 g .Data.Product.proj₂ ∘ f .Data.Product.proj₂)
≈ ⊗.F₁ g ∘ ⊗.F₁ f

lemmas.interchange:
{A : Obj} {A' = B : Obj} {A'' = i : Obj} {B = j : Obj}
{B' = k : Obj} {B'' : Obj}
{a : A ⇒ B} {b : j ⇒ k} {c : B ⇒ i} {d : k ⇒ B''} →
c ⊗₁ d ∘ a ⊗₁ b ≈ (c ∘ a) ⊗₁ (d ∘ b)

lemmas.⊗-resp-≈ˡ:
{h.X = A : Obj} {h.Y = B : Obj} {f = i : A ⇒ B} {h = j : A ⇒ B}
{g.X = k : Obj} {g.Y = B'' : Obj} {g = a : k ⇒ B''} →
i ≈ j → i ⊗₁ a ≈ j ⊗₁ a

lemma_normal.interchange:
{A : Obj} {A' = B : Obj} {A'' = i : Obj} {B = j : Obj}
{B' = k : Obj} {B'' : Obj}
{a : A ⇒ B} {b : j ⇒ k} {c : B ⇒ i} {d : k ⇒ B''} →
⊗.F₁ (c , d) ∘ ⊗.F₁ (a , b) ≈ ⊗.F₁ (c ∘ a , d ∘ b)

lemma_normal.⊗-resp-≈ˡ:
{h.X = A : Obj} {h.Y = B : Obj} {f = i : A ⇒ B} {h = j : A ⇒ B}
{g.X = k : Obj} {g.Y = B'' : Obj} {g = a : k ⇒ B''} →
i ≈ j → ⊗.F₁ (i , a) ≈ ⊗.F₁ (j , a)
